// Pending sign-in session — survives the browser round-trip / pyor:// re-entry.
//
// Stored in sessionStorage (not localStorage): it's a short-lived,
// per-tab/per-launch artifact, cleared once the callback is consumed. Holds
// the CSRF `state` we match against the value GitHub echoes back.

const KEY = 'pyor:oauth-session';

export interface OAuthSession {
  state: string;
  reauth: boolean;
  startedAt: number;
}

export function saveSession(s: OAuthSession): void {
  try {
    sessionStorage.setItem(KEY, JSON.stringify(s));
  } catch {
    // sessionStorage unavailable — the callback will fail the state check
    // and surface as a 'cancelled'/'expired' error, which is acceptable.
  }
}

export function readSession(): OAuthSession | null {
  try {
    const raw = sessionStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as OAuthSession) : null;
  } catch {
    return null;
  }
}

export function clearSession(): void {
  try {
    sessionStorage.removeItem(KEY);
  } catch {
    // No-op.
  }
}

/** Fresh CSRF nonce for a new sign-in attempt. */
function newStateNonce(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `s_${Date.now().toString(36)}_${Math.random().toString(36).slice(2)}`;
  }
}

/** Validate the callback's `state` against the stored session. */
export function matchesSession(state: string | undefined): boolean {
  const s = readSession();
  return !!s && !!state && s.state === state;
}
