// Finish on GitHub — single browser visit (install + authorize merged).
// "Request user authorization during installation" is ON for the Pyor
// GitHub App, so the repo picker + approval happen in ONE browser trip.
// No device code anywhere. state: 'waiting' | 'verifying'; reauth=true →
// returning user who only needs to re-authorize (no repo picker).

import { CheckCircle2, ExternalLink, Folder, Loader2 } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { PyorWindow } from '../../ui/PyorWindow';
import { PermissionsAside } from './PermissionsAside';

interface Props {
  state: 'waiting' | 'verifying';
  reauth?: boolean;
  onReopen?: () => void;
  onUseToken?: () => void;
  onBack?: () => void;
  width?: number;
  height?: number;
  fluid?: boolean;
}

const SAMPLE_REPOS: [string, string][] = [
  ['acme/web', 'private'],
  ['acme/api', 'private'],
  ['acme/mobile', 'private'],
];

export function BrowserSignInScreen({
  state,
  reauth = false,
  onReopen,
  onUseToken,
  onBack,
  width = 920,
  height = 640,
  fluid = false,
}: Props) {
  const verifying = state === 'verifying';
  const showRepos = !verifying && !reauth;

  return (
    <PyorWindow
      width={width}
      height={height}
      title="Pyor"
      subtitle="Sign in with GitHub"
      fluid={fluid}
      hideStatusBar
      flushLeft
      toolbar={
        onBack ? (
          <Button variant="ghost" size="sm" onClick={onBack}>
            Back
          </Button>
        ) : undefined
      }
    >
      <div className="flex min-h-0 flex-1">
        <div className="flex flex-1 flex-col bg-background px-9 py-8">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/80">
            Approve in your browser
          </div>
          <h1 className="mt-2 font-display text-[20px] font-semibold tracking-tight text-foreground">
            {verifying
              ? 'Welcome back'
              : reauth
                ? 'Re-authorize Pyor on GitHub'
                : 'Finish signing in on GitHub'}
          </h1>
          <p className="mt-1.5 max-w-[440px] text-[13px] leading-relaxed text-muted-foreground">
            {verifying
              ? 'GitHub sent you back to Pyor. Hang tight while we finish signing you in — no codes to copy.'
              : reauth
                ? 'We opened GitHub in your browser. Approve Pyor to re-authorize — you’ll come straight back to this window.'
                : 'We opened GitHub in your browser. Approve Pyor — and pick the repositories it can read — then you’ll come straight back here. Nothing to copy or paste.'}
          </p>

          {showRepos && (
            <div className="mt-6 max-w-[440px] overflow-hidden rounded-xl border bg-card shadow-sm">
              <div className="flex items-center gap-2 border-b bg-muted/40 px-4 py-2.5 text-[12px] font-medium text-foreground">
                <Folder className="size-3.5 text-muted-foreground" />
                Only select repositories
                <span className="ml-auto whitespace-nowrap rounded bg-muted px-1.5 py-0.5 text-[10.5px] font-normal text-muted-foreground">
                  choose on GitHub
                </span>
              </div>
              <ul className="divide-y divide-border/60">
                {SAMPLE_REPOS.map(([repo, vis]) => (
                  <li
                    key={repo}
                    className="flex items-center gap-2.5 px-4 py-2 text-[12.5px]"
                  >
                    <CheckCircle2 className="size-3.5 shrink-0 text-pyor-pass" />
                    <span className="font-mono text-foreground">{repo}</span>
                    <Badge variant="secondary" className="px-1.5 py-0 text-[9.5px]">
                      {vis}
                    </Badge>
                  </li>
                ))}
                <li className="px-4 py-2 text-[12px] text-muted-foreground/70">
                  + 15 more selected
                </li>
              </ul>
            </div>
          )}

          <div
            className={`flex max-w-[440px] flex-col items-center justify-center rounded-2xl border bg-muted/40 px-6 text-center ${showRepos ? 'mt-5 py-6' : 'mt-7 py-10'}`}
          >
            {verifying ? (
              <>
                <span className="inline-flex size-12 items-center justify-center rounded-full bg-pyor-pass/10 ring-1 ring-pyor-pass/30">
                  <CheckCircle2 className="size-6 text-pyor-pass" />
                </span>
                <div className="mt-3 text-[13.5px] font-medium text-foreground">
                  Approved — bringing you in…
                </div>
                <div className="mt-1 text-[12px] text-muted-foreground">
                  Fetching your repositories &amp; notifications.
                </div>
              </>
            ) : (
              <>
                <Loader2 className="size-7 animate-spin text-muted-foreground/70" />
                <div className="mt-3 text-[13.5px] font-medium text-foreground">
                  Waiting for you to approve in your browser…
                </div>
                <div className="mt-1 text-[12px] text-muted-foreground">
                  We opened{' '}
                  <span className="font-medium text-foreground">github.com</span>{' '}
                  — approve Pyor there.
                </div>
              </>
            )}
          </div>

          {!verifying && (
            <div className="mt-4">
              <Button
                variant="outline"
                className="h-11 gap-2 rounded-lg"
                onClick={onReopen}
              >
                <ExternalLink className="size-4 text-muted-foreground" />
                Reopen browser
              </Button>
            </div>
          )}

          <div className="flex-1" />
          {!verifying && (
            <div className="mt-6 flex items-center gap-2 border-t pt-4 text-[12px] text-muted-foreground">
              <span>Browser didn't open?</span>
              <button
                type="button"
                onClick={onReopen}
                className="font-medium text-foreground hover:underline"
              >
                Reopen browser
              </button>
              <span className="text-border">·</span>
              <button
                type="button"
                onClick={onUseToken}
                className="font-medium text-foreground hover:underline"
              >
                Use a token instead
              </button>
            </div>
          )}
        </div>

        <PermissionsAside />
      </div>
    </PyorWindow>
  );
}
