// Connected — plan-aware success confirmation (first connect only).
// Returning users skip this (the index gate sends them straight in).

import { useState } from 'react';
import { useNavigate } from '@tanstack/react-router';
import {
  Check,
  ExternalLink,
  Inbox,
  Info,
  KeyRound,
  Lock,
  ShieldCheck,
  User,
  Users,
} from 'lucide-react';
import type { ReactNode } from 'react';
import { GithubMark } from '../../auth/GithubMark';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { INBOX_DEFAULTS } from '../../router/search';
import type { Entitlement } from '../../auth/oauthBroker';
import type { AuthMethod } from '../../auth/tokenStore';
import {
  canManageBilling,
  openManageSeats,
} from '../../billing/entitlement';
import { UpgradeDialog } from '../../billing/UpgradeDialog';
import { PyorWindow } from '../../ui/PyorWindow';

interface ConnectedViewer {
  login: string;
  name: string;
  email?: string | null;
  avatar_url?: string;
}

interface Props {
  viewer: ConnectedViewer;
  method: AuthMethod;
  entitlement: Entitlement | null;
  onOpen?: () => void;
  width?: number;
  height?: number;
  fluid?: boolean;
}

export function ConnectedScreen({
  viewer,
  method,
  entitlement,
  onOpen,
  width = 920,
  height = 640,
  fluid = false,
}: Props) {
  const navigate = useNavigate();
  const [upgradeOpen, setUpgradeOpen] = useState(false);
  const verified = method === 'github-app';
  const seats = entitlement?.seats ?? [];
  const isPaid = verified && seats.length > 0;
  // Per-org now (ADR 0020). This celebratory first-connect summary shows the
  // single-org case inline; multi-org users manage each org from Settings.
  const soleSeat = seats.length === 1 ? seats[0] : undefined;
  const canManage = canManageBilling(soleSeat?.role ?? null);

  const openPier =
    onOpen ?? (() => void navigate({ to: '/inbox', search: INBOX_DEFAULTS }));

  const initials = (viewer.name || viewer.login)
    .split(/[-_ ]/)
    .map((s) => s[0])
    .filter(Boolean)
    .slice(0, 2)
    .join('')
    .toUpperCase();

  return (
    <PyorWindow
      width={width}
      height={height}
      title="Pyor"
      subtitle="Connected"
      fluid={fluid}
      hideStatusBar
      flushLeft
    >
      <div className="flex flex-1 flex-col items-center justify-center bg-panel px-8 py-10 text-center">
        <div className="relative">
          {verified ? (
            <Avatar className="size-16">
              <AvatarImage src={viewer.avatar_url} alt={viewer.login} />
              <AvatarFallback className="text-[20px] font-semibold">
                {initials}
              </AvatarFallback>
            </Avatar>
          ) : (
            <span className="inline-flex size-16 items-center justify-center rounded-full border bg-card text-muted-foreground">
              <User className="size-7" />
            </span>
          )}
          <span
            className={`absolute -bottom-1 -right-1 inline-flex size-6 items-center justify-center rounded-full ring-2 ring-background ${verified ? 'bg-pyor-pass' : 'bg-pyor-warn'}`}
          >
            {verified ? (
              <Check className="size-3.5 text-white" strokeWidth={3} />
            ) : (
              <KeyRound className="size-3.5 text-white" />
            )}
          </span>
        </div>

        <h1 className="mt-5 font-display text-[21px] font-semibold tracking-tight text-foreground">
          {verified ? `Connected as @${viewer.login}` : 'Connected with a token'}
        </h1>
        <p className="mt-1.5 text-[13px] text-muted-foreground">
          {verified
            ? [viewer.name, viewer.email].filter(Boolean).join(' · ')
            : 'Identity not verified · token in your Keychain'}
        </p>

        <div className="mt-6 w-full max-w-[420px] overflow-hidden rounded-xl border bg-card text-left shadow-sm">
          <Row label="Identity">
            {verified ? (
              <span className="inline-flex items-center gap-1.5 text-pyor-pass">
                <ShieldCheck className="size-3.5" />
                Verified · GitHub sign-in
              </span>
            ) : (
              <span className="inline-flex items-center gap-1.5 text-pyor-warn">
                <KeyRound className="size-3.5" />
                Unverified · token
              </span>
            )}
          </Row>
          <Row label="Plan">
            {isPaid ? (
              <span className="inline-flex items-center gap-1.5">
                <span className="font-medium text-foreground">
                  {soleSeat ? `${soleSeat.name} · Pro` : `Pro · ${seats.length} organizations`}
                </span>
                {soleSeat && (
                  <Badge variant="default" className="px-1.5 py-0 text-[9.5px]">
                    Seat {soleSeat.index} of {soleSeat.total}
                  </Badge>
                )}
              </span>
            ) : verified ? (
              <span>Free · personal</span>
            ) : (
              <span>
                Free only{' '}
                <span className="text-muted-foreground/70">
                  · paid needs GitHub sign-in
                </span>
              </span>
            )}
          </Row>
          <Row label="Repository access">
            {verified ? '18 repositories' : 'From token scopes'}
          </Row>
          <Row label="Stored on" last>
            <code className="font-mono text-[11.5px]">This Mac · Keychain</code>
          </Row>
        </div>

        {isPaid && soleSeat && (
          <div className="mt-3 flex w-full max-w-[420px] items-center gap-3 rounded-xl border bg-card px-4 py-3 text-left shadow-sm">
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-2 text-[12.5px] font-semibold text-foreground">
                <Users className="size-3.5 text-muted-foreground" />
                Team seats
              </div>
              <Progress
                value={(soleSeat.index / soleSeat.total) * 100}
                className="mt-1.5 h-1.5"
              />
              <div className="mt-1 text-[11.5px] text-muted-foreground">
                {soleSeat.index} of {soleSeat.total} seats used · billed per seat
              </div>
            </div>
            {canManage ? (
              <Button
                variant="outline"
                size="sm"
                className="shrink-0 gap-1.5"
                onClick={() => openManageSeats(soleSeat.githubOrgId)}
              >
                <ExternalLink className="size-3.5 text-muted-foreground" />
                Manage seats
              </Button>
            ) : (
              <span className="inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap text-[11.5px] text-muted-foreground/70">
                <Lock className="size-3.5" />
                Managed by your org owner
              </span>
            )}
          </div>
        )}

        {isPaid && !soleSeat && (
          <div className="mt-3 flex w-full max-w-[420px] items-center gap-2.5 rounded-xl border bg-card px-4 py-3 text-left text-[12px] text-muted-foreground shadow-sm">
            <Users className="size-4 shrink-0 text-muted-foreground/70" />
            <span className="flex-1">
              You hold a seat in {seats.length} organizations. Manage each org's
              seats &amp; billing in Settings.
            </span>
            <button
              type="button"
              onClick={() => void navigate({ to: '/settings' })}
              className="shrink-0 font-medium text-foreground hover:underline"
            >
              Open Settings
            </button>
          </div>
        )}

        {verified && !isPaid && (
          <div className="mt-3 flex w-full max-w-[420px] items-center gap-2.5 rounded-xl border bg-card px-4 py-3 text-left text-[12px] text-muted-foreground shadow-sm">
            <Users className="size-4 shrink-0 text-muted-foreground/70" />
            <span className="flex-1">
              Reviewing with a team? Upgrade your org for shared seats &amp;
              analytics.
            </span>
            <button
              type="button"
              onClick={() => setUpgradeOpen(true)}
              className="shrink-0 font-medium text-foreground hover:underline"
            >
              Compare plans
            </button>
          </div>
        )}

        {!verified && (
          <div className="mt-3 flex w-full max-w-[420px] items-center gap-2.5 rounded-xl border border-pyor-warn/40 bg-pyor-warn/10 px-4 py-3 text-left text-[12px] text-pyor-warn shadow-sm">
            <Info className="size-4 shrink-0 text-pyor-warn" />
            <span className="flex-1">
              Paid &amp; team features need a verified account.
            </span>
            <button
              type="button"
              onClick={() => void navigate({ to: '/connect' })}
              className="inline-flex shrink-0 items-center gap-1 font-medium hover:underline"
            >
              <GithubMark className="size-3.5" />
              Switch to GitHub sign-in
            </button>
          </div>
        )}

        <div className="mt-6 w-full max-w-[420px]">
          <Button
            className="h-11 w-full gap-2.5 rounded-lg text-sm font-semibold"
            onClick={openPier}
          >
            <Inbox className="!size-[18px]" />
            Open Pyor
          </Button>
        </div>
      </div>
      <UpgradeDialog open={upgradeOpen} onOpenChange={setUpgradeOpen} />
    </PyorWindow>
  );
}

function Row({
  label,
  children,
  last,
}: {
  label: string;
  children: ReactNode;
  last?: boolean;
}) {
  return (
    <div
      className={`flex items-center gap-3 px-4 py-2.5 text-[12.5px] ${last ? '' : 'border-b border-border/60'}`}
    >
      <span className="w-32 shrink-0 text-muted-foreground">{label}</span>
      <span className="flex-1 text-foreground">{children}</span>
    </div>
  );
}
