// Buy-seats org picker (ADR 0019). A free user who admins one or more GitHub
// orgs picks which org to upgrade; we hand off to a broker-created Polar
// checkout (owner-gated server-side). Only orgs the user is an admin/owner of
// are shown — those are the only ones they can buy seats for.

import { useQuery } from '@tanstack/react-query';
import { ExternalLink, Loader2, Users } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { listAdminOrgs } from '../github/client';
import { openComparePlans, openOrgCheckout } from './entitlement';

export function UpgradeDialog({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const {
    data: orgs,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ['admin-orgs'],
    queryFn: listAdminOrgs,
    enabled: open,
    staleTime: 5 * 60_000,
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[440px]">
        <DialogHeader>
          <DialogTitle>Upgrade your team to Pro</DialogTitle>
          <DialogDescription>
            Pick the GitHub organization to buy seats for. You can only upgrade
            orgs you own or admin.
          </DialogDescription>
        </DialogHeader>

        <div className="mt-1">
          {isLoading && (
            <div className="flex items-center gap-2 px-1 py-6 text-[13px] text-muted-foreground">
              <Loader2 className="size-4 animate-spin" />
              Finding your organizations…
            </div>
          )}

          {isError && (
            <div className="px-1 py-6 text-[13px] text-muted-foreground">
              Couldn't read your organizations from GitHub. Try again, or{' '}
              <button
                type="button"
                onClick={() => openComparePlans()}
                className="font-medium text-foreground hover:underline"
              >
                see plans
              </button>
              .
            </div>
          )}

          {orgs && orgs.length === 0 && (
            <div className="rounded-lg border bg-muted/40 px-4 py-5 text-[13px] leading-relaxed text-muted-foreground">
              You're not an owner or admin of any GitHub organization, so there's
              nothing to buy seats for yet. Pyor stays free for your personal
              repos.
            </div>
          )}

          {orgs && orgs.length > 0 && (
            <ul className="flex flex-col gap-2">
              {orgs.map((org) => (
                <li
                  key={org.id}
                  className="flex items-center gap-3 rounded-lg border bg-card px-3.5 py-2.5"
                >
                  <span className="flex size-7 shrink-0 items-center justify-center rounded-md bg-muted text-muted-foreground">
                    <Users className="size-4" />
                  </span>
                  <span className="min-w-0 flex-1 truncate font-mono text-[13px] text-foreground">
                    {org.login}
                  </span>
                  <Button
                    size="sm"
                    className="shrink-0 gap-1.5"
                    onClick={() => openOrgCheckout(org.id)}
                  >
                    <ExternalLink className="size-3.5" />
                    Buy seats
                  </Button>
                </li>
              ))}
            </ul>
          )}
        </div>

        <p className="mt-2 text-[11.5px] leading-relaxed text-muted-foreground">
          Checkout opens on Polar (our billing provider) — seats activate
          automatically when payment settles, and each member who joins claims a
          seat in this organization (access is per organization).
        </p>
      </DialogContent>
    </Dialog>
  );
}
