// Orchestrates the GitHub-App sign-in state machine (ADR 0019).
//
//   start → (open browser / mock auto-advance) → waiting
//        → [callback: code+state] → verifying → completeSignIn
//        → setCredential + getViewer + resolveEntitlement
//        → connected  |  error
//
// Mounted at `/connect` (fresh start) and `/connect/callback` (the
// web redirect / Electron pyor:// re-entry, carrying code+state).

import { useEffect, useRef, useState } from 'react';
import { useNavigate } from '@tanstack/react-router';
import {
  broker,
  isMockBroker,
  BrokerError,
  type AuthErrorKind,
  type Entitlement,
} from '../../auth/oauthBroker';
import { setCredential } from '../../auth/tokenStore';
import {
  clearSession,
  matchesSession,
  readSession,
  saveSession,
} from '../../auth/oauthSession';
import { resolveEntitlement } from '../../billing/entitlement';
import { getViewer, hasInstallationRepos } from '../../github/client';
import { mockViewer } from '../../auth/mockBroker';
import { openExternalUrl } from '../../desktop/openExternal';
import { isElectron } from '../../desktop/electronBridge';
import { BrowserSignInScreen } from './BrowserSignInScreen';
import { ConnectedScreen } from './ConnectedScreen';
import { AuthErrorScreen } from './AuthErrorScreen';

interface ConnectedViewer {
  login: string;
  name: string;
  email?: string | null;
  avatar_url?: string;
}

type Phase =
  | { t: 'waiting'; reauth: boolean }
  | { t: 'verifying' }
  | { t: 'connected'; viewer: ConnectedViewer; entitlement: Entitlement | null }
  | { t: 'error'; kind: AuthErrorKind };

function mapCallbackError(error: string): AuthErrorKind {
  if (error === 'access_denied') return 'cancelled';
  if (error === 'expired_token') return 'expired';
  return 'offline';
}

export function ConnectController({
  callback,
}: {
  callback?: { code?: string; state?: string; error?: string };
}) {
  const navigate = useNavigate();
  const [phase, setPhase] = useState<Phase>({
    t: callback ? 'verifying' : 'waiting',
    reauth: readSession()?.reauth ?? false,
  } as Phase);
  const ran = useRef(false);
  const authorizeUrl = useRef<string | null>(null);

  useEffect(() => {
    if (ran.current) return;
    ran.current = true;
    if (callback) {
      void complete(callback.code, callback.state, callback.error);
    } else {
      void start();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function start() {
    try {
      const { authorizeUrl: url, state, reauth } = await broker.startSignIn({
        reauth: readSession()?.reauth,
      });
      authorizeUrl.current = url;
      saveSession({ state, reauth, startedAt: Date.now() });
      setPhase({ t: 'waiting', reauth });
      if (isMockBroker) {
        // No real browser round-trip — act as if GitHub redirected back.
        await complete('mock_code', state);
      } else if (isElectron()) {
        // Desktop: open the system browser; GitHub returns via pyor://.
        openExternalUrl(url);
      } else {
        // Web: full-page SAME-TAB redirect. A new tab would lose the
        // sessionStorage holding our CSRF state, failing the callback.
        window.location.assign(url);
      }
    } catch (e) {
      setPhase({ t: 'error', kind: e instanceof BrokerError ? e.kind : 'offline' });
    }
  }

  async function complete(code?: string, state?: string, error?: string) {
    if (error) {
      setPhase({ t: 'error', kind: mapCallbackError(error) });
      return;
    }
    if (!code || !state || (!isMockBroker && !matchesSession(state))) {
      // Missing/forged callback — treat as an expired/abandoned attempt.
      setPhase({ t: 'error', kind: 'expired' });
      return;
    }
    setPhase({ t: 'verifying' });
    try {
      const tokens = await broker.completeSignIn(code, state);
      const viewer = isMockBroker
        ? mockViewer
        : await getViewer(tokens.accessToken);
      // The OAuth callback signed them in, but verify the App can actually see
      // repos. Authorized-but-not-installed (or zero repos selected) → route to
      // the install page instead of an empty app. One check, not a poll. We
      // check BEFORE persisting the credential so a reload doesn't strand them
      // "signed in" with no access.
      if (!isMockBroker && !(await hasInstallationRepos(tokens.accessToken))) {
        setPhase({ t: 'error', kind: 'no-repos' });
        return;
      }
      setCredential({
        accessToken: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        expiresAt: tokens.expiresAt,
        method: 'github-app',
      });
      // Entitlement is soft (ADR 0019) — never block sign-in on it. If the
      // broker can't resolve/sign it, sign in anyway (treated as free).
      let entitlement: Entitlement | null = null;
      try {
        entitlement = await resolveEntitlement(tokens.accessToken);
      } catch {
        entitlement = null;
      }
      clearSession();
      setPhase({ t: 'connected', viewer, entitlement });
    } catch (e) {
      setPhase({ t: 'error', kind: e instanceof BrokerError ? e.kind : 'offline' });
    }
  }

  const onReopen = () => {
    if (!authorizeUrl.current) void navigate({ to: '/connect' });
    else if (isElectron()) openExternalUrl(authorizeUrl.current);
    else window.location.assign(authorizeUrl.current);
  };
  const onUseToken = () => void navigate({ to: '/setup' });
  const onBack = () => void navigate({ to: '/welcome' });
  // Re-run the flow in place. navigate('/connect') was a no-op when already
  // mounted here (same route => no remount => start() never re-ran).
  const onRetry = () => void start();

  if (phase.t === 'connected') {
    return (
      <ConnectedScreen
        fluid
        viewer={phase.viewer}
        method="github-app"
        entitlement={phase.entitlement}
      />
    );
  }
  if (phase.t === 'error') {
    return (
      <AuthErrorScreen
        fluid
        kind={phase.kind}
        onRetry={onRetry}
        onUseToken={onUseToken}
        onBack={onBack}
      />
    );
  }
  return (
    <BrowserSignInScreen
      fluid
      state={phase.t === 'verifying' ? 'verifying' : 'waiting'}
      reauth={phase.t === 'waiting' ? phase.reauth : false}
      onReopen={onReopen}
      onUseToken={onUseToken}
      onBack={onBack}
    />
  );
}
