// Auth error / edge states (ADR 0019). Shared layout: icon tile, title,
// body, diagnostics card, ghost secondary + solid primary.

import type { ComponentType } from 'react';
import {
  Clock,
  ExternalLink,
  Folder,
  RefreshCw,
  Users,
  WifiOff,
  XCircle,
  type LucideIcon,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { GithubMark } from '../../auth/GithubMark';
import type { AuthErrorKind } from '../../auth/oauthBroker';
import { openExternalUrl } from '../../desktop/openExternal';
import { APP_INSTALL_URL } from '../../github/appInstall';
import { PyorWindow } from '../../ui/PyorWindow';

interface Config {
  icon: LucideIcon;
  tone: 'warn' | 'zinc';
  title: string;
  body: string;
  diag: [string, string][];
}

const CFG: Record<AuthErrorKind, Config> = {
  expired: {
    icon: Clock,
    tone: 'warn',
    title: 'That sign-in link expired',
    body: 'Sign-in links are valid for a few minutes. Start again and approve Pyor in your browser.',
    diag: [
      ['Reason', 'link_expired'],
      ['Broker', 'api.pyor.review'],
    ],
  },
  cancelled: {
    icon: XCircle,
    tone: 'zinc',
    title: 'Sign-in was cancelled',
    body: 'You closed the GitHub tab or clicked Cancel before approving Pyor. No access was granted.',
    diag: [
      ['Reason', 'access_denied'],
      ['Granted', 'nothing — no token issued'],
    ],
  },
  'no-repos': {
    icon: Folder,
    tone: 'warn',
    title: "Pyor can't see any repositories yet",
    body: 'Pyor is installed on your account, but no repositories were selected. Choose which repos Pyor can read on GitHub, then recheck.',
    diag: [
      ['App', 'installed'],
      ['Repositories', '0 selected'],
      ['Needs', 'at least one repo'],
    ],
  },
  'org-approval': {
    icon: Users,
    tone: 'warn',
    title: 'Your org needs to approve Pyor',
    body: 'An owner of your organization must approve the Pyor GitHub App before it can read that org’s repositories. You can request access right from GitHub.',
    diag: [
      ['Status', 'approval required'],
      ['Your repos', 'still available'],
    ],
  },
  offline: {
    icon: WifiOff,
    tone: 'zinc',
    title: "Can't reach GitHub",
    body: 'Pyor couldn’t reach GitHub to finish signing you in. Check your connection and try again.',
    diag: [
      ['Endpoint', 'github.com'],
      ['Error', 'NetworkError · timeout'],
    ],
  },
};

interface Props {
  kind: AuthErrorKind;
  onRetry?: () => void;
  onUseToken?: () => void;
  onBack?: () => void;
  width?: number;
  height?: number;
  fluid?: boolean;
}

export function AuthErrorScreen({
  kind,
  onRetry,
  onUseToken,
  onBack,
  width = 920,
  height = 640,
  fluid = false,
}: Props) {
  const c = CFG[kind];
  const Icon = c.icon;

  // Primary action varies by kind; secondary is "use a token" except where a
  // recheck makes more sense.
  const primary: {
    label: string;
    icon: ComponentType<{ className?: string }>;
    run?: () => void;
  } =
    kind === 'no-repos'
      ? { label: 'Choose repositories on GitHub', icon: ExternalLink, run: () => openExternalUrl(APP_INSTALL_URL) }
      : kind === 'org-approval'
        ? { label: 'Request access on GitHub', icon: ExternalLink, run: () => openExternalUrl(APP_INSTALL_URL) }
        : kind === 'offline'
          ? { label: 'Retry', icon: RefreshCw, run: onRetry }
          : { label: 'Try again', icon: GithubMark, run: onRetry };

  const secondary =
    kind === 'no-repos'
      ? { label: 'Recheck access', run: onRetry }
      : { label: 'Use a token instead', run: onUseToken };

  const PrimaryIcon = primary.icon;

  return (
    <PyorWindow
      width={width}
      height={height}
      title="Pyor"
      subtitle="Sign in with GitHub"
      fluid={fluid}
      hideStatusBar
      flushLeft
      toolbar={
        onBack ? (
          <Button variant="ghost" size="sm" onClick={onBack}>
            Back to sign-in
          </Button>
        ) : undefined
      }
    >
      <div className="flex flex-1 flex-col items-center justify-center bg-panel px-8 py-10 text-center">
        <div className="inline-flex size-14 items-center justify-center rounded-2xl border bg-card shadow-sm">
          <Icon
            className={`size-6 ${c.tone === 'warn' ? 'text-pyor-warn' : 'text-muted-foreground'}`}
            strokeWidth={1.8}
          />
        </div>
        <h1 className="mt-4 font-display text-[19px] font-semibold tracking-tight text-foreground">
          {c.title}
        </h1>
        <p className="mx-auto mt-1.5 max-w-[440px] text-[13px] leading-relaxed text-muted-foreground">
          {c.body}
        </p>

        <div className="mt-4 w-full max-w-[420px] overflow-hidden rounded-xl border bg-card text-left text-[12px] shadow-sm">
          {c.diag.map(([k, v], i) => (
            <div
              key={k}
              className={`flex items-center gap-3 px-4 py-2 ${i < c.diag.length - 1 ? 'border-b border-border/60' : ''}`}
            >
              <span className="w-28 shrink-0 text-muted-foreground">{k}</span>
              <span className="flex-1 font-mono text-[11.5px] text-foreground">
                {v}
              </span>
            </div>
          ))}
        </div>

        <div className="mt-5 flex items-center gap-2.5">
          <Button variant="ghost" onClick={secondary.run}>
            {secondary.label}
          </Button>
          <Button className="gap-2" onClick={primary.run}>
            <PrimaryIcon className="size-4" />
            {primary.label}
          </Button>
        </div>
      </div>
    </PyorWindow>
  );
}
